import 'dart:convert';import 'package:flutter/material.dart';import 'package:shared_preferences/shared_preferences.dart';import '../models/moment.dart';
class MomentService extends ChangeNotifier{static const key='orbia_moments_v1';bool loaded=false;List<Moment> moments=[];
Future<void> load()async{final p=await SharedPreferences.getInstance();try{final r=p.getString(key);if(r!=null)moments=(jsonDecode(r) as List).map((e)=>Moment.fromJson(Map<String,dynamic>.from(e))).toList();}catch(_){moments=[];}if(moments.isEmpty){final n=DateTime.now();moments=[Moment(id:'trip',title:'Summer escape',note:'The trip I have been waiting for.',date:n.add(const Duration(days:42)),type:MomentType.trip,favorite:true,saved:true,createdAt:n),Moment(id:'launch',title:'Launch day',note:'A date worth remembering.',date:n.add(const Duration(days:11)),type:MomentType.event,favorite:false,saved:true,createdAt:n)];await _save();}loaded=true;notifyListeners();}
Future<void> _save()async{final p=await SharedPreferences.getInstance();await p.setString(key,jsonEncode(moments.map((e)=>e.toJson()).toList()));}
List<Moment> get upcoming{final l=moments.where((e)=>!e.isPast).toList();l.sort((a,b)=>a.date.compareTo(b.date));return l;}List<Moment> get archive{final l=moments.where((e)=>e.isPast).toList();l.sort((a,b)=>b.date.compareTo(a.date));return l;}List<Moment> get favorites=>moments.where((e)=>e.favorite).toList();List<Moment> get saved=>moments.where((e)=>e.saved).toList();
List<Moment> search(String q){q=q.trim().toLowerCase();if(q.isEmpty)return moments;return moments.where((m)=>m.title.toLowerCase().contains(q)||m.note.toLowerCase().contains(q)||m.type.name.contains(q)).toList();}
Future<void> add(Moment m)async{moments=[m,...moments];await _save();notifyListeners();}Future<void> update(Moment m)async{moments=moments.map((e)=>e.id==m.id?m:e).toList();await _save();notifyListeners();}Future<void> toggleFavorite(String id)async{final m=moments.firstWhere((e)=>e.id==id);await update(m.copyWith(favorite:!m.favorite));}Future<void> toggleSaved(String id)async{final m=moments.firstWhere((e)=>e.id==id);await update(m.copyWith(saved:!m.saved));}Future<void> delete(String id)async{moments=moments.where((e)=>e.id!=id).toList();await _save();notifyListeners();}}
